"""Tensor-parallel linear layers (Megatron-style).

Weight layout follows torch.nn.Linear: weight has shape (out_features, in_features)
and y = x @ weight.T + bias.

- ColumnParallelLinear: the output dimension is partitioned. Each rank holds
  weight[out_start:out_end, :] and bias[out_start:out_end]. Local outputs are
  all-gathered and concatenated along the last dimension.
- RowParallelLinear: the input dimension is partitioned. Each rank holds
  weight[:, in_start:in_end] and the full bias. Partial outputs are summed with
  all-reduce, then the bias is added.
"""

import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _split_last_dim(x, world_size, rank):
    if world_size == 1:
        return x
    chunk = x.size(-1) // world_size
    return x.narrow(-1, rank * chunk, chunk).contiguous()


def _all_reduce(x):
    if _world_size() == 1:
        return x
    x = x.contiguous().clone()
    dist.all_reduce(x, op=dist.ReduceOp.SUM)
    return x


def _all_gather_last_dim(x):
    world_size = _world_size()
    if world_size == 1:
        return x
    x = x.contiguous()
    tensors = [torch.empty_like(x) for _ in range(world_size)]
    dist.all_gather(tensors, x)
    return torch.cat(tensors, dim=-1).contiguous()


class _CopyToParallelRegion(torch.autograd.Function):
    """Identity in forward, all-reduce of the gradient in backward."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad_output):
        return _all_reduce(grad_output)


class _ReduceFromParallelRegion(torch.autograd.Function):
    """All-reduce in forward, identity in backward."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x)

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


class _GatherFromParallelRegion(torch.autograd.Function):
    """All-gather along last dim in forward, take local slice in backward."""

    @staticmethod
    def forward(ctx, x):
        return _all_gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad_output):
        return _split_last_dim(grad_output, _world_size(), _rank())


class _ScatterToParallelRegion(torch.autograd.Function):
    """Take local slice along last dim in forward, all-gather in backward."""

    @staticmethod
    def forward(ctx, x):
        return _split_last_dim(x, _world_size(), _rank())

    @staticmethod
    def backward(ctx, grad_output):
        return _all_gather_last_dim(grad_output)


class ColumnParallelLinear(nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.world_size = _world_size()
        self.rank = _rank()
        if out_features % self.world_size != 0:
            raise ValueError(
                f"out_features ({out_features}) must be divisible by world_size ({self.world_size})"
            )
        self.in_features = in_features
        self.out_features = out_features
        self.output_size_per_partition = out_features // self.world_size

        master_weight = torch.as_tensor(master_weight).detach()
        assert master_weight.shape == (out_features, in_features), (
            f"master_weight shape {tuple(master_weight.shape)} != {(out_features, in_features)}"
        )
        start = self.rank * self.output_size_per_partition
        end = start + self.output_size_per_partition
        self.weight = nn.Parameter(master_weight[start:end, :].clone().contiguous())

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    self.output_size_per_partition,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        local_out = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(local_out)


class RowParallelLinear(nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.world_size = _world_size()
        self.rank = _rank()
        if in_features % self.world_size != 0:
            raise ValueError(
                f"in_features ({in_features}) must be divisible by world_size ({self.world_size})"
            )
        self.in_features = in_features
        self.out_features = out_features
        self.input_size_per_partition = in_features // self.world_size

        master_weight = torch.as_tensor(master_weight).detach()
        assert master_weight.shape == (out_features, in_features), (
            f"master_weight shape {tuple(master_weight.shape)} != {(out_features, in_features)}"
        )
        start = self.rank * self.input_size_per_partition
        end = start + self.input_size_per_partition
        self.weight = nn.Parameter(master_weight[:, start:end].clone().contiguous())

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features, dtype=master_weight.dtype, device=master_weight.device
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input (split it here) or an already-partitioned input.
        if x.size(-1) == self.in_features and self.world_size > 1:
            x = _ScatterToParallelRegion.apply(x)
        elif x.size(-1) != self.input_size_per_partition:
            raise ValueError(
                f"Input last dim {x.size(-1)} matches neither in_features ({self.in_features}) "
                f"nor partition size ({self.input_size_per_partition})"
            )
        partial = F.linear(x, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
